#include <stdlib.h>

int *findOrder(int numCourses, int **prerequisites, int prerequisitesSize,
               int *prerequisitesColSize, int *returnSize)
{
    int *indeg = calloc((size_t)numCourses, sizeof(int));
    /* 用 CSR（压缩稀疏行）存邻接表：head/next 数组 */
    int *head = malloc(sizeof(int) * (size_t)numCourses);
    int *next = malloc(sizeof(int) * (size_t)(prerequisitesSize ? prerequisitesSize : 1));
    for (int i = 0; i < numCourses; i++) head[i] = -1;
    for (int i = 0; i < prerequisitesSize; i++) {
        int a = prerequisites[i][0], b = prerequisites[i][1];
        indeg[a]++;
        next[i] = head[b];
        head[b] = i;
    }
    int *queue = malloc(sizeof(int) * (size_t)(numCourses ? numCourses : 1));
    int front = 0, back = 0;
    for (int i = 0; i < numCourses; i++) if (indeg[i] == 0) queue[back++] = i;
    int *order = malloc(sizeof(int) * (size_t)(numCourses ? numCourses : 1));
    int n = 0;
    while (front < back) {
        int u = queue[front++];
        order[n++] = u;
        for (int e = head[u]; e != -1; e = next[e]) {
            int v = prerequisites[e][0];
            if (--indeg[v] == 0) queue[back++] = v;
        }
    }
    free(indeg); free(head); free(next); free(queue);
    if (n != numCourses) { free(order); *returnSize = 0; return NULL; }
    *returnSize = n;
    return order;
}
